"""Recalculate every compact-page metric directly from preserved JSONL, without Java."""
import argparse
import collections
import hashlib
import json
from pathlib import Path
import statistics


HERE = Path(__file__).resolve().parent
ARMS = ['current-off', 'current-dense', 'compact-dense']
FIXTURES = ['fanout', 'shared-tail']
METRICS = ['totalNs', 'allThreadAllocatedBytes', 'callerThreadAllocatedBytes',
           'prepareNs', 'evaluateNs', 'firstRowAfterEvaluateNs', 'consumeNs',
           'closeNs', 'ledgerPeakBytes', 'connectionNs', 'retainedReadNs']
PAIRS = [('compact-dense', 'current-dense'), ('compact-dense', 'current-off'),
         ('current-dense', 'current-off')]
EXPECTED = {'fanout': (1152000, '3123987218479850048', 55),
            'shared-tail': (1048576, '8327963502356915200', 10)}


def read(path):
    return json.loads(path.read_text())


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write_new(path, value):
    with path.open('x') as stream:
        json.dump(value, stream, indent=2, sort_keys=True)
        stream.write('\n')


def describe(values):
    return {'median': statistics.median(values), 'minimum': min(values),
            'maximum': max(values), 'values': values}


def flatten_numbers(mapping, prefix=''):
    result = {}
    for name, value in mapping.items():
        key = prefix + name
        if isinstance(value, dict):
            result.update(flatten_numbers(value, key + '.'))
        elif type(value) in (int, float):
            result[key] = value
    return result


def table(headers, rows):
    return '\n'.join(['| ' + ' | '.join(headers) + ' |',
                      '| ' + ' | '.join(['---'] * len(headers)) + ' |'] +
                     ['| ' + ' | '.join(str(x) for x in row) + ' |' for row in rows])


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--study', type=Path, default=HERE / 'comparison-v1')
    parser.add_argument('--output', type=Path, default=HERE / 'raw-analysis-v1')
    args = parser.parse_args()
    study, output = args.study.resolve(strict=True), args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    protocol = read(study / 'used-protocol.json')
    recorded = read(study / 'runs.json')
    summary = read(study / 'summary.json')
    recorded_by_key = {(x['fixture'], x['round'], x['arm']): x for x in recorded}
    raw = {}
    forks = []
    hashes = {}
    chronology = []
    route_counts = collections.Counter()
    for round_index, order in enumerate(protocol['balancedOrders']):
        for fixture_position, fixture in enumerate(protocol['fixtureOrdersByRound'][round_index]):
            for position, arm in enumerate(order):
                name = f'round-{round_index:02d}-{fixture_position:02d}-{fixture}-{position:02d}-{arm}'
                folder = study / name
                entries = [json.loads(line) for line in (folder / 'samples.jsonl').read_text().splitlines()]
                metadata, samples = entries[0], entries[1:]
                assert metadata['type'] == 'metadata' and len(samples) == 13
                assert [s['stage'] for s in samples] == ['warmup'] * 8 + ['measurement'] * 5
                assert [s['iteration'] for s in samples] == list(range(-8, 5))
                assert metadata['arm'] == arm
                rows, checksum, adjacency_hits = EXPECTED[fixture]
                for sample in samples:
                    assert sample['arm'] == arm and sample['valid'] and sample['complete']
                    assert sample['rows'] == rows and sample['checksum'] == checksum
                    assert sample['rowCountValid'] and sample['checksumValid'] and sample['partialMembershipValid']
                    assert fixture != 'shared-tail' or sample['exactBagValid']
                    assert sample['ledgerBeforeBytes'] == sample['ledgerAfterBytes'] == 0
                    assert sample['autoRequested'] and sample['auto'] and sample['omittedSelections'] == 0
                    counters = sample['counters']
                    assert counters['semanticNativeCompiles'] == counters['irOpened'] == 1
                    assert counters['irRows'] == rows
                    assert counters['coordinateAdmissions']['opened'] == int(arm != 'current-off')
                    assert counters['coordinateAdmissions']['initialAdmissionRefused'] == 0
                    assert counters['coordinateAdmissions']['growthAdmissionRefused'] == 0
                    assert len(sample['successfulSelections']) == 1
                    selection = sample['successfulSelections'][0]
                    expected_strategy = 'irKernelInterpreted' if sample['iteration'] == -8 else 'irKernel'
                    assert selection['strategy'] == expected_strategy and 'forced' not in selection['mode']
                    route_counts[(fixture, sample['stage'], selection['strategy'])] += 1
                    if sample['stage'] == 'measurement':
                        assert counters['compiledBinds'] == 1 and counters['interpretedBinds'] == 0
                    adjacency = sample['adjacency']
                    assert adjacency['lookupHits'] == adjacency_hits and adjacency['plannerStatsHits'] == 1
                    assert adjacency['stateBefore'] == adjacency['stateAfter'] == 'ACTIVE'
                    assert (adjacency['currentRevisionBefore'] == adjacency['currentRevisionAfter'] ==
                            adjacency['appliedRevisionBefore'] == adjacency['appliedRevisionAfter'] == 1)
                    assert adjacency['exactMisses'] == 0 and adjacency['fallbacks'] == {}
                    assert sample['totalNs'] == sum(sample[k] for k in
                        ['connectionNs', 'prepareNs', 'evaluateNs', 'consumeNs', 'closeNs', 'retainedReadNs'])
                process = read(folder / 'process-result.json')
                assert process['exitCode'] == 0 and process['failure'] is None
                audit = read(folder / 'root-host-audit.json')
                assert audit['harnessReturned'] and audit['harnessFailureClass'] is None
                assert audit['semanticNativeCompilesTotal'] == 13
                assert audit['hostedGenericTotal'] == audit['unhostedHardDeclinesTotal'] == 0
                chronology.append({'directory': name, **process})
                measured = samples[8:]
                medians = {k: statistics.median(s[k] for s in measured) for k in METRICS}
                original = recorded_by_key[(fixture, round_index, arm)]
                assert all(medians[k] == value for k, value in original['medians'].items())
                assert original['samples'] == samples and original['metadata'] == metadata
                assert original['rootAudit'] == audit and original['routeTierHistogramMatchesFirstFixtureFork']
                counter_keys = flatten_numbers(measured[0]['counters']).keys()
                counters = {key: describe([flatten_numbers(s['counters'])[key] for s in measured])
                            for key in counter_keys}
                for key, value in original['counterMedians'].items():
                    assert counters[key]['median'] == value
                fork = {'fixture': fixture, 'roundIndex': round_index, 'roundNumber': round_index + 1,
                        'arm': arm, 'position': position, 'directory': str(folder),
                        'medians': medians, 'metricSamples': {k: [s[k] for s in measured] for k in METRICS},
                        'counterStatistics': counters,
                        'coldFirstQuery': {k: samples[0][k] for k in METRICS},
                        'warmupSamples': [{k: s[k] for k in METRICS} for s in samples[:8]],
                        'adjacencyLookupHitsPerQuery': adjacency_hits,
                        'callerAllocationDifferenceSamples': [s['allThreadAllocatedBytes'] -
                            s['callerThreadAllocatedBytes'] for s in measured]}
                forks.append(fork)
                raw[(fixture, round_index, arm)] = (metadata, samples, fork)
                for filename in ['samples.jsonl', 'root-host-audit.json', 'process-result.json', 'command.json']:
                    path = folder / filename
                    hashes[str(path)] = digest(path)
    assert len(forks) == 36 and len(recorded) == 36
    assert all(a['finishedEpochNs'] <= b['startedEpochNs'] for a, b in zip(chronology, chronology[1:]))
    groups = []
    for fixture in FIXTURES:
        for arm in ARMS:
            selected = [raw[fixture, r, arm] for r in range(6)]
            measured = [sample for _, samples, _ in selected for sample in samples[8:]]
            counter_keys = flatten_numbers(measured[0]['counters']).keys()
            groups.append({'fixture': fixture, 'arm': arm,
                'medianOfJvmMedians': {k: describe([f['medians'][k] for _, _, f in selected]) for k in METRICS},
                'allThirtyMeasuredSamples': {k: describe([s[k] for s in measured]) for k in METRICS},
                'coldFirstQuery': {k: describe([samples[0][k] for _, samples, _ in selected]) for k in METRICS},
                'warmupByPosition': [{k: describe([samples[i][k] for _, samples, _ in selected])
                                      for k in METRICS} for i in range(8)],
                'counterStatisticsAllThirtyMeasuredSamples':
                    {k: describe([flatten_numbers(s['counters'])[k] for s in measured]) for k in counter_keys},
                'otherThreadAllocation': describe([s['allThreadAllocatedBytes'] - s['callerThreadAllocatedBytes']
                                                   for s in measured])})
    comparisons = []
    for fixture in FIXTURES:
        for candidate, comparator in PAIRS:
            by_metric = {k: [raw[fixture, r, candidate][2]['medians'][k] /
                            raw[fixture, r, comparator][2]['medians'][k] for r in range(6)] for k in METRICS}
            match = next(c for c in summary['comparisons'] if c['fixture'] == fixture and
                         c['candidate'] == candidate and c['comparator'] == comparator)
            for key, value in match['medianRatios'].items():
                assert statistics.median(by_metric[key]) == value
                assert [min(by_metric[key]), max(by_metric[key])] == match['ratioRanges'][key]
                assert by_metric[key] == [p['ratios'][key] for p in match['pairs']]
            comparisons.append({'fixture': fixture, 'candidate': candidate, 'comparator': comparator,
                'statistics': {k: describe(values) for k, values in by_metric.items()},
                'latencyRatiosBelowOne': sum(v < 1 for v in by_metric['totalNs']),
                'latencyRatiosAboveOne': sum(v > 1 for v in by_metric['totalNs'])})
    compact = {c['fixture']: c for c in comparisons if c['comparator'] == 'current-dense'}
    gates = {
        'sharedTailLedgerEveryPairAtMostQuarter': max(compact['shared-tail']['statistics']['ledgerPeakBytes']['values']) <= .25,
        'sharedTailAllocationEveryPairLower': max(compact['shared-tail']['statistics']['allThreadAllocatedBytes']['values']) < 1,
        **{fixture + 'MedianLatencyAtMostOne': compact[fixture]['statistics']['totalNs']['median'] <= 1
           for fixture in FIXTURES},
        **{fixture + 'EveryLatencyAtMostOnePointOne': compact[fixture]['statistics']['totalNs']['maximum'] <= 1.1
           for fixture in FIXTURES}}
    assert all(gates.values()) == summary['engineeringAcceptance']['passed']
    assert summary['complete'] and summary['errors'] == []
    post = read(study / 'post-run-preservation.json')
    assert post['identityFilesUnchanged'] and all(post['runtimeIdentitiesUnchanged'].values())
    analysis = {'format': 1, 'method': 'Direct raw JSONL recalculation; all five measured queries per JVM; all six within-round pairs; no cross-fixture pooling.',
        'sourceProtocolSha256': digest(study / 'used-protocol.json'), 'scriptSha256': digest(Path(__file__)),
        'study': str(study), 'forkCount': len(forks), 'warmupQueryCount': 288, 'measuredQueryCount': 180,
        'rawQueryCount': 468, 'recomputedMediansAndRatiosMatchDriverExactly': True,
        'serialProcessesNonoverlapping': True, 'chronology': chronology, 'rawInputSha256': hashes,
        'routeCounts': [{'fixture': k[0], 'stage': k[1], 'strategy': k[2], 'count': v}
                        for k, v in sorted(route_counts.items())],
        'forks': forks, 'armStatistics': groups, 'comparisons': comparisons,
        'engineeringAcceptanceGates': gates, 'engineeringAcceptancePassed': all(gates.values()),
        'postRunPreservation': post}
    write_new(output / 'analysis.json', analysis)
    sections = ['# Recalculated numerical tables', '',
                'All values come from raw `samples.jsonl` files. Human rounds are 1–6; raw indices are 0–5.', '']
    group_index = {(g['fixture'], g['arm']): g for g in groups}
    for fixture in FIXTURES:
        sections += ['## ' + fixture, '', '### Six paired rounds', '']
        rows = []
        for r in range(6):
            values = {arm: raw[fixture, r, arm][2]['medians'] for arm in ARMS}
            rows.append([r + 1, *[f"{values[arm]['totalNs'] / 1e9:.9f}" for arm in ARMS],
                         f"{values['compact-dense']['totalNs'] / values['current-dense']['totalNs']:.9f}",
                         f"{values['compact-dense']['totalNs'] / values['current-off']['totalNs']:.9f}",
                         f"{values['current-dense']['totalNs'] / values['current-off']['totalNs']:.9f}"])
        sections += [table(['Round', 'OFF s', 'Current DENSE s', 'Compact DENSE s', 'Compact/current',
                           'Compact/OFF', 'Current/OFF'], rows), '', '### Absolute warmed metrics', '']
        rows = []
        for key in METRICS:
            divisor = 1e6 if key.endswith('Ns') else 1
            label = key + (' (ms)' if divisor == 1e6 else ' (bytes)')
            values = []
            for arm in ARMS:
                stat = group_index[fixture, arm]['medianOfJvmMedians'][key]
                values.append(f"{stat['median'] / divisor:.6f} [{stat['minimum'] / divisor:.6f}, {stat['maximum'] / divisor:.6f}]")
            rows.append([label, *values])
        sections += [table(['Metric: median [range of six JVM medians]', *ARMS], rows), '', '### Cold first query', '']
        rows = []
        for key in METRICS:
            divisor = 1e6 if key.endswith('Ns') else 1
            values = []
            for arm in ARMS:
                stat = group_index[fixture, arm]['coldFirstQuery'][key]
                values.append(f"{stat['median'] / divisor:.6f} [{stat['minimum'] / divisor:.6f}, {stat['maximum'] / divisor:.6f}]")
            rows.append([key + (' (ms)' if divisor == 1e6 else ' (bytes)'), *values])
        sections += [table(['Metric: median [range of six first queries]', *ARMS], rows), '', '### Allocation by round', '']
        rows = []
        for r in range(6):
            values = {arm: raw[fixture, r, arm][2]['medians']['allThreadAllocatedBytes'] for arm in ARMS}
            rows.append([r + 1, *[f"{values[arm]:,}" for arm in ARMS],
                         f"{values['compact-dense'] / values['current-dense']:.9f}"])
        sections += [table(['Round', 'OFF bytes', 'Current DENSE bytes', 'Compact DENSE bytes', 'Compact/current'], rows), '',
                     '### Counters across all 30 measured queries per arm', '']
        counter_names = group_index[fixture, ARMS[0]]['counterStatisticsAllThirtyMeasuredSamples'].keys()
        rows = []
        for key in counter_names:
            values = []
            for arm in ARMS:
                stat = group_index[fixture, arm]['counterStatisticsAllThirtyMeasuredSamples'][key]
                values.append(f"{stat['median']:g} [{stat['minimum']:g}, {stat['maximum']:g}]")
            rows.append([key, *values])
        sections += [table(['Counter: median [range]', *ARMS], rows), '']
    (output / 'numeric-tables.md').write_text('\n'.join(sections))
    print(json.dumps({'output': str(output), 'rawCounts': [36, 468, 180],
                      'allRecomputedValuesMatchDriver': True, 'acceptancePassed': all(gates.values()),
                      'gates': gates}))


if __name__ == '__main__':
    main()
